# (nome, desconta saldo, precisa de aprovação, meio dia, cor)
TIPOS = [
    ("Férias", True, True, True, "carvao"),
    ("Falta justificada", False, True, False, "ardosia"),
    ("Baixa médica", False, False, False, "ardosia"),
    ("Licença parental", False, False, False, "aco"),
    ("Formação", False, True, True, "aco"),
]


def preencher(apps, schema_editor):
    """Tipos de origem por restaurante; os pedidos já feitos passam a
    férias, com os dias úteis contados sem feriados nacionais."""
    import datetime

    from vacations.holidays import national_holidays

    Restaurant = apps.get_model("core", "Restaurant")
    AbsenceType = apps.get_model("vacations", "AbsenceType")
    VacationRequest = apps.get_model("vacations", "VacationRequest")
    for restaurant in Restaurant.objects.all():
        if not AbsenceType.objects.filter(restaurant=restaurant).exists():
            AbsenceType.objects.bulk_create([
                AbsenceType(restaurant=restaurant, name=n, deducts_balance=d, requires_approval=a, half_days=h, color=c)
                for n, d, a, h, c in TIPOS
            ])
    for pedido in VacationRequest.objects.select_related("worker").all():
        ferias = AbsenceType.objects.get(restaurant_id=pedido.worker.restaurant_id, name="Férias")
        dias, dia = 0, pedido.start_date
        while dia <= pedido.end_date:
            if dia.weekday() < 5 and dia not in national_holidays(dia.year):
                dias += 1
            dia += datetime.timedelta(days=1)
        pedido.absence_type = ferias
        pedido.days_taken = dias
        pedido.save(update_fields=["absence_type", "days_taken"])


